import java.nio.file.Path;
import java.nio.file.Files;
import java.io.IOException;

public class ConfigReader {
    public String loadConfig() throws IOException {
        // Modern way: Path.of() since Java 11
        Path configPath = Path.of("config", "app.properties");

        // Older way: Paths.get() since Java 7
        Path logPath = Path.of("logs/output.txt");

        // Path doesn't care if file exists yet
        System.out.println("Config at: " + configPath.toAbsolutePath());

        // Use with Files utility for actual operations
        if (Files.exists(configPath)) {
            return Files.readString(configPath);  // Java 11+
        }
        return "default.config";
    }
}

import java.nio.file.*;
import java.io.IOException;
import java.util.List;

public class FileOperations {
    public void demonstrateFiles() throws IOException {
        Path configPath = Path.of("config/app.properties");
        Path logPath = Path.of("logs/output.txt");

        // Read entire text file in one line
        String config = Files.readString(configPath);

        // Write text file with UTF-8 encoding
        Files.writeString(logPath, "Application started\n");

        // Create nested directories if they don't exist
        Files.createDirectories(Path.of("logs/archive/2024"));

        // Copy with options to replace existing
        Files.copy(logPath, Path.of("logs/backup.txt"), 
                   StandardCopyOption.REPLACE_EXISTING);

        // Check existence and type
        if (Files.exists(configPath) && !Files.isDirectory(configPath)) {
            List<String> lines = Files.readAllLines(configPath);
            System.out.println("Config has " + lines.size() + " lines");
        }
    }
}

