import java.nio.file.Path;

public class PathManipulation {
    public void demonstratePathOps() {
        Path projectRoot = Path.of("/home/user/myapp");
        Path configDir = Path.of("config");

        // resolve: append relative path to base
        Path configFile = projectRoot.resolve("config/database.yaml");
        System.out.println(configFile);  // /home/user/myapp/config/database.yaml

        // Also works with Path argument
        Path logFile = projectRoot.resolve(Path.of("logs/app.log"));

        // relativize: compute relative path between two locations
        Path docsPath = Path.of("/home/user/myapp/docs/api.html");
        Path relative = projectRoot.relativize(docsPath);
        System.out.println(relative);  // docs/api.html

        // normalize: clean up redundant dots
        Path messy = Path.of("config/../logs/./archive/../current/app.log");
        Path clean = messy.normalize();
        System.out.println(clean);  // logs/current/app.log
    }
}

import java.nio.file.*;
import static java.nio.file.StandardWatchEventKinds.*;
import java.io.IOException;

public class ConfigWatcher {
    public void watchConfigDir() throws IOException, InterruptedException {
        Path configDir = Path.of("config");
        WatchService watcher = FileSystems.getDefault().newWatchService();

        // Register directory with events to watch
        configDir.register(watcher, ENTRY_CREATE, ENTRY_MODIFY, ENTRY_DELETE);

        System.out.println("Watching " + configDir + " for changes...");

        while (true) {
            // Block until an event occurs
            WatchKey key = watcher.take();

            for (WatchEvent<?> event : key.pollEvents()) {
                WatchEvent.Kind<?> kind = event.kind();
                Path fileName = (Path) event.context();

                System.out.println(kind.name() + ": " + fileName);

                if (kind == ENTRY_MODIFY && fileName.toString().endsWith(".properties")) {
                    reloadConfig(configDir.resolve(fileName));
                }
            }

            key.reset();  // Must reset to receive further events
        }
    }

    private void reloadConfig(Path path) {
        System.out.println("Reloading config from " + path);
    }
}
